#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    /* No argument supplied */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse the argument as a decimal integer */
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* Invalid number (no conversion or extra characters) */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* n must be positive and not larger than 1\u202F000\u202F000 */
    if (n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Compute the sum of proper divisors of n */
    long sum = 0;
    for (long i = 1; i * i <= n; ++i) {
        if (n % i == 0) {
            long d = n / i;
            if (i != n) sum += i;          // i is a divisor (i < n always here)
            if (d != i && d != n) sum += d; // paired divisor
        }
    }

    /* Classify the number */
    if (sum == n) {
        printf("n=%ld sum=%ld perfect\n", n, sum);
    } else if (sum > n) {
        printf("n=%ld sum=%ld abundant\n", n, sum);
    } else {
        printf("n=%ld sum=%ld deficient\n", n, sum);
    }

    return 0;
}
